 String[] presetKeys={"auto","unplug","shuffle","repeat","boot","bootPlay","launch","resume","nonstop","stopAfter","shuffledOrder","autoDj","wave"};
 void preset(int mode){android.content.SharedPreferences q=getSharedPreferences("presets",0);if(mode==0){EditText e=new EditText(this);new AlertDialog.Builder(this).setTitle("ชื่อพรีเซ็ต").setView(e).setPositiveButton("บันทึก",(d,w)->{String n=e.getText().toString().trim();if(n.isEmpty())return;JSONObject j=new JSONObject();try{for(String k:presetKeys)j.put(k,p.getBoolean(k,!(k.equals("shuffle")||k.equals("stopAfter")||k.equals("shuffledOrder")||k.equals("wave"))));j.put("repeatMode",repeatMode());j.put("fadeMs",p.getInt("fadeMs",5000));q.edit().putString(n,j.toString()).apply();Toast.makeText(this,"บันทึกแล้ว",0).show();}catch(Exception ex){}}).setNegativeButton("ยกเลิก",null).show();}else{String[] names=q.getAll().keySet().toArray(new String[0]);Arrays.sort(names);new AlertDialog.Builder(this).setTitle(mode==1?"โหลดพรีเซ็ต":"ลบพรีเซ็ต").setItems(names,(d,w)->{if(mode==2){new AlertDialog.Builder(this).setMessage("ลบ "+names[w]+"?").setPositiveButton("ลบ",(x,y)->q.edit().remove(names[w]).apply()).setNegativeButton("ยกเลิก",null).show();}else try{JSONObject j=new JSONObject(q.getString(names[w],"{}"));android.content.SharedPreferences.Editor ed=p.edit();for(String k:presetKeys)if(j.has(k))ed.putBoolean(k,j.getBoolean(k));ed.putInt("repeatMode",j.optInt("repeatMode",j.optBoolean("repeat",true)?2:0));ed.putInt("fadeMs",j.optInt("fadeMs",5000));ed.apply();recreate();}catch(Exception ex){}}).show();}}
